/* prog60_inventory_sim.c
 * Reimplementation of the original inventory simulation program.
 * The observable behaviour (stdout) matches the original binary.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(int argc, char **argv)
{
    /* There are exactly 5 SKUs: 0 … 4 */
    long stock[5] = {0};

    /* Price of each SKU – these are the constants used by the original binary */
    const long price[5] = {10, 20, 30, 40, 50};

    long revenue = 0;

    /* Arguments are processed three at a time:
       <op> <sku> <qty>
       where <op> is a single‑character string: "S" (sell) or "R" (restock) */
    for (int i = 1; i + 2 < argc; i += 3) {
        char *op  = argv[i];
        long  sku = strtol(argv[i + 1], NULL, 10);
        long  qty = strtol(argv[i + 2], NULL, 10);

        /* SKU must be in the range 0‑4 */
        if (sku < 0 || sku >= 5) {
            puts("INVALID_SKU");
            continue;
        }

        if (strcmp(op, "R") == 0) {                 /* RESTOCK */
            if (qty < 0) {
                printf("INSUFFICIENT_STOCK sku=%ld\n", sku);
                continue;
            }
            stock[sku] += qty;
            printf("RESTOCK sku=%ld qty=%ld\n", sku, qty);
        }
        else if (strcmp(op, "S") == 0) {            /* SELL */
            if (qty < 0 || stock[sku] < qty) {
                printf("INSUFFICIENT_STOCK sku=%ld\n", sku);
                continue;
            }
            stock[sku] -= qty;
            revenue += price[sku] * qty;
            printf("SELL sku=%ld qty=%ld revenue+=%ld\n",
                   sku, qty, price[sku] * qty);
        }
        else {                                      /* unknown operation */
            puts("INVALID_OP");
        }
    }

    /* final report */
    printf("FINAL stock=");
    for (int i = 0; i < 5; ++i) {
        printf("%ld", stock[i]);
        if (i < 4)
            putchar(',');
    }
    printf(" revenue=%ld\n", revenue);
    return 0;
}
